# Define the helper functions that would normally be imported
def find_changed_pairs(inputs, outputs):
    """Identify which (input, output) pairs actually differ."""
    changed = []
    for i, (inp, outp) in enumerate(zip(inputs, outputs)):
        if inp != outp:
            changed.append((i, inp, outp))
    return changed

def find_minimal_edit(s_in, s_out):
    """Find the minimal edit from s_in to s_out."""
    # Simple approach: find first differing character position
    min_len = min(len(s_in), len(s_out))

    # Find first difference
    for i in range(min_len):
        if s_in[i] != s_out[i]:
            # Check if we're inserting or deleting
            if len(s_in) > len(s_out):
                # Delete at position i
                return s_in[i], "", i
            elif len(s_in) < len(s_out):
                # Insert at position i  
                return "", s_out[i], i
            else:
                # Replace at position i
                return s_in[i], s_out[i], i

    # If we reach here, one string is prefix of the other
    if len(s_in) > len(s_out):
        # Delete at end
        return s_in[min_len], "", min_len
    elif len(s_in) < len(s_out):
        # Insert at end
        return "", s_out[min_len], min_len
    else:
        # Strings are identical (shouldn't happen in our case)
        return "", "", -1

def propose_rule_candidates(s_in, s_out):
    """Propose rule candidates from a changed pair."""
    # This is a simplified version - in practice this would be more complex
    old_sub, new_sub, pos = find_minimal_edit(s_in, s_out)

    # For now, just return the basic replacement
    if old_sub != "" and new_sub != "":
        return [(old_sub, new_sub)]
    elif old_sub != "":
        # Deletion case
        return [(old_sub, "")]
    elif new_sub != "":
        # Insertion case  
        return [("", new_sub)]
    else:
        return []

def apply_rules(strings, rules):
    """Apply a sequence of rules to strings."""
    result = strings[:]
    for pattern, replacement in rules:
        result = [s.replace(pattern, replacement) for s in result]
    return result

def score_rules(inputs, outputs, rules):
    """Score how well rules match the input/output pairs."""
    predicted = apply_rules(inputs, rules)
    correct = sum(1 for i, o in zip(predicted, outputs) if i == o)
    return correct / len(inputs)

def find_over_applications(inputs, outputs, rules):
    """Find which inputs are incorrectly modified by rules."""
    predicted = apply_rules(inputs, rules)
    over_apps = []
    for i, (inp, outp, pred) in enumerate(zip(inputs, outputs, predicted)):
        if pred != outp and inp != outp:  # Only count if originally different
            over_apps.append((i, inp, pred))
    return over_apps

def simulate_rule_chain(s, rules):
    """Simulate applying rules step by step to a string."""
    trace = []
    current = s
    for pattern, replacement in rules:
        prev = current
        current = current.replace(pattern, replacement)
        trace.append({
            'step': len(trace),
            'pattern': pattern,
            'replacement': replacement,
            'before': prev,
            'after': current
        })
    return trace

# Now let's work with the actual data
inputs = ['xf', 'ihybw', 'xuuhv', 'ukwhb', 'vczwv']
outputs = ['xdx', 'ihekfbw', 'xhxhxhv', 'hxkwhb', 'vczwv']

changed = find_changed_pairs(inputs, outputs)
print("Changed pairs:")
for idx, s_in, s_out in changed:
    print(f"  {idx}: '{s_in}' -> '{s_out}'")

